          (\[Xi]w*mass[MW]^2 - mass[MZ]^2)^2))/((-1 + \[Xi]w)*\[Xi]w*
        mass[MW]^6) + (mass[MZ]^4*sorttad[{mass[MW], mass[MW], mass[MZ]}, 
         {1, 1, 1}])/((-1 + \[Xi]w)^2*mass[MW]^8) - 
      (mass[MZ]^4*sorttad[{mass[MW], Sqrt[\[Xi]w]*mass[MW], mass[MZ]}, 
         {1, 1, 1}])/((-1 + \[Xi]w)^2*mass[MW]^8) - 
      (mass[MZ]^4*sorttad[{Sqrt[\[Xi]w]*mass[MW], mass[MW], mass[MZ]}, 
         {1, 1, 1}])/((-1 + \[Xi]w)^2*\[Xi]w^2*mass[MW]^8) + 
      (mass[MZ]^4*sorttad[{Sqrt[\[Xi]w]*mass[MW], Sqrt[\[Xi]w]*mass[MW], 
          mass[MZ]}, {1, 1, 1}])/((-1 + \[Xi]w)^2*\[Xi]w^2*mass[MW]^8)))/
    (2048*d*Pi^8*sw^2))
